export const COMMUNES: readonly Commune[] = ROWS.map(([code, wilaya, fr, ar, aliases, alsoIn]) => ({
  code, wilaya, fr, ar, aliases: aliases ?? [], alsoIn: alsoIn ?? null,
}));

/** Communes of one wilaya (including the 2 unsure ones offered under both), sorted by French name */
export function communesOf(wilaya: number): Commune[] {
  return COMMUNES.filter((c) => c.wilaya === wilaya || c.alsoIn === wilaya).sort((a, b) => a.fr.localeCompare(b.fr, "fr"));
}
